    public virtual void handleTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // {
        //   "channel": "trades",
        //   "data": [
        //     {
        //       "h": 80062522,
        //       "s": "BTC",
        //       "a": "0.00001",
        //       "p": "89471",
        //       "d": "close_short",
        //       "tc": "normal",
        //       "t": 1765018379085,
        //       "li": 1559885104
        //     }
        //   ]
        // }
        //
        List<object> entry = this.safeList(message, "data", new List<object>() {});
        IDictionary<string, object> first = this.safeDict(entry, 0, new Dictionary<string, object>() {});
        string? marketId = this.safeString(first, "s");
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? symbol = ((string)GetValue(market, "symbol"));
        if (!(inOp(this.trades, symbol)))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            var stored = new ArrayCache(limit);
            ((IDictionary<string,object>)this.trades)[(string)symbol] = stored;
        }
        object trades = getValue(this.trades, symbol);
        for (int i = 0; isLessThan(i, entry.Count); postFixIncrement(ref i))
        {
            IDictionary<string, object> data = this.safeDict(entry, i, new Dictionary<string, object>() {});
            Dictionary<string, object> trade = this.parseWsTrade(data);
            callDynamically(trades, "append", new object[] {trade});
        }
        string messageHash = add("trade:", symbol);
        callDynamically(client, "resolve", new object[] {trades, messageHash});
    }

    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        // fetchMyTrades
        //
        //    {
        //       "h": 80063441, // history id
        //       "i": 1559912767, // oid
        //       "I": null, // cloid
        //       "u": "BrZp5bidJ3WUvceSq7X78bhjTfZXeezzGvGEV4hAYKTa", // account address
        //       "s": "BTC",  // symbol
        //       "p": "89477", // price
        //       "o": "89505", // entry price
        //       "a": "0.00036", // amount
        //       "te": "fulfill_taker",
        //       "ts": "close_long",
        //       "tc": "normal", // trade type
        //       "f": "0.012885", // fee
        //       "n": "-0.022965", // pnl
        //       "t": 1765018588190,
        //       "li": 1559912767
        //     }
        //
        // fetchTrades
        //
        //     {
        //       "h": 80062522,
        //       "s": "BTC",
        //       "a": "0.00001",
        //       "p": "89471",
        //       "d": "close_short",
        //       "tc": "normal",
        //       "t": 1765018379085,
        //       "li": 1559885104
        //     }
        //
        Int64? timestamp = this.safeInteger(trade, "t");
        string? price = this.safeString(trade, "p");
        string? amount = this.safeString(trade, "a");
        string? marketId = this.safeString(trade, "s");
        market = this.safeMarket(marketId, market);
        object symbol = getValue(market, "symbol");
        string? id = this.safeString(trade, "h");
        string? fee = this.safeString(trade, "f");
        string? side = this.safeString2(trade, "ts", "d");
        if (side == "open_long")
        {
            side = "buy";
        } else if (side == "close_long")
        {
            side = "sell";
        } else if (side == "open_short")
        {
            side = "sell";
        } else if (side == "close_short")
        {
            side = "buy";
        }
        string? eventType = this.safeString(trade, "te");
        string? takerOrMaker = null;
        if ((eventType != null))
        {
            takerOrMaker = (eventType == "fulfill_maker") ? "maker" : "taker";
        }
        string? orderId = this.safeString(trade, "i");
        // public trades have no orderId
        if ((orderId == null))
        {
            takerOrMaker = null;
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "id", id },
            { "order", this.safeString(trade, "i") },
            { "type", null },
            { "side", side },
            { "takerOrMaker", takerOrMaker },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", new Dictionary<string, object>() {
                { "cost", fee },
                { "currency", "USDC" },
            } },
        }, market);
    }

